template<int THREADS, int MODE, bool LOG>
__device__ __forceinline__ void body(const float* q,const float* k,const float* wq,const float* wk,float* qo,float* ko,
   int n_rows,float eps, unsigned long long* lg){
  unsigned long long t0=0; if(LOG) t0=gt();
  constexpr int RPC=THREADS/16;
  const int n_cta=(n_rows+RPC-1)/RPC; const int G=2*n_cta;
  int bid=blockIdx.x;
  if(MODE==1){ if(bid&1) return; bid>>=1; }          // cluster pair with an idle partner
  int b=bid; const bool is_k=b>=n_cta; if(is_k) b-=n_cta;
  const float* x=is_k?k:q; const float* w=is_k?wk:wq; float* y=is_k?ko:qo;
