#define K(name,T,M,L,ATTR) extern "C" __global__ void ATTR __launch_bounds__(T) name(const float* q,const float* k,const float* wq,const float* wk,float* qo,float* ko,int n_rows,float eps,unsigned long long* lg){body<T,M,L>(q,k,wq,wk,qo,ko,n_rows,eps,lg);}
K(pL,256,0,true,)
K(cL,256,0,true,__cluster_dims__(2,1,1))
K(p0,256,0,false,)
K(c0,256,0,false,__cluster_dims__(2,1,1))
K(cidle,256,1,false,__cluster_dims__(2,1,1))
K(pidle,256,1,false,)
'''
V=['p0','c0','cidle','pidle','pL','cL']
ks={n:bp.cuda_kernel(SRC,n) for n in V}
wq=torch.randn(48,128,device='cuda'); wk=torch.randn(48,128,device='cuda')
lg=torch.zeros(8192,dtype=torch.int64,device='cuda')
def mk(n,nr):
    G=2*((nr+15)//16)*(2 if 'idle' in n else 1); kk=ks[n]
    return lambda q,k,wq,wk,qo,ko: kk((G,),(256,),q,k,wq,wk,qo,ko,nr,1e-6,lg)
for tok in (128,256):
    nr=tok*48; q=torch.randn(nr,128,device='cuda'); k=torch.randn_like(q); qo=torch.empty_like(q); ko=torch.empty_like(q)
    res={n:[] for n in V}
    for rep in range(8):
        for n in (V if rep%2==0 else V[::-1]):
            res[n].append(bp.harness_time(mk(n,nr),[q,k,wq,wk],[qo,ko],warmup=5,rep=40))
    base=np.median(res['p0'])
    print(tok,'CUPTI', ' '.join(f"{n}:{np.median(res[n]):.3f}({100*(np.median(res[n])/base-1):+.1f}%)" for n in V))
    G=2*((nr+15)//16)
    for n in ('pL','cL'):
        sp=[];endq=[]
        for r in range(40):
            bp.flush_l2(); torch.cuda.synchronize(); mk(n,nr)(q,k,wq,wk,qo,ko); torch.cuda.synchronize()
            a=lg[:2*G].view(G,2).cpu().numpy().astype(np.int64); m=a[:,0].min()
            sp.append(a[:,1].max()-m); endq.append(np.percentile(a[:,1]-m,[50,90,99]))
        print('  ',n,'in-kernel span median ns',int(np.median(sp)),'p25/p75',int(np.percentile(sp,25)),int(np.percentile(sp,75)),' end p50/p90/p99',np.median(np.array(endq),0).astype(int).tolist())

