  const float* x=is_k?k:q; const float* w=is_k?wk:wq; float* y=is_k?ko:qo;
  const int row=b*16+(threadIdx.x>>4); const int c=(threadIdx.x&15)*8;
  const int head=row%H;
  uint64_t pol; asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;":"=l"(pol));
  float xv[8],wv[8],yv[8];
  if(MODE==2){ for(int i=0;i<8;++i) yv[i]=eps; st8_h(y+(size_t)row*D+c,yv,pol); return; }
  ld8_h(x+(size_t)row*D+c,xv); ld8_nc(w+(size_t)head*D+c,wv);
