   :: "l"(p),"f"(v[0]),"f"(v[1]),"f"(v[2]),"f"(v[3]),"f"(v[4]),"f"(v[5]),"f"(v[6]),"f"(v[7]),"l"(pol) : "memory");}
template<int THREADS, int R>
__device__ __forceinline__ void body(const float* q,const float* k,const float* wq,const float* wk,float* qo,float* ko,
   int n_tok,float eps){
  constexpr int RPC=THREADS/16, NG=H/RPC;
  const int n_cta=NG*((n_tok+R-1)/R);
  int b=blockIdx.x; const bool is_k=b>=n_cta; if(is_k) b-=n_cta;
  const float* x=is_k?k:q; const float* w=is_k?wk:wq; float* y=is_k?ko:qo;
  const int g=b%NG, tok0=(b/NG)*R, head=g*RPC+(threadIdx.x>>4), c=(threadIdx.x&15)*8;
  float xv[R][8],wv[8];
  #pragma unroll
  for(int j=0;j<R;++j){ if(R==1||tok0+j<n_tok) ld8_h(x+((size_t)(tok0+j)*H+head)*D+c,xv[j]); else for(int i=0;i<8;++i) xv[j][i]=0.f; }
  ld8_nc(w+(size_t)head*D+c,wv);
  uint64_t pol; asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;":"=l"(pol));
  #pragma unroll
  for(int j=0;j<R;++j){
    float s=0.f; for(int i=0;i<8;++i) s=fmaf(xv[j][i],xv[j][i],s);
    s+=__shfl_xor_sync(0xffffffffu,s,8); s+=__shfl_xor_sync(0xffffffffu,s,4);
    s+=__shfl_xor_sync(0xffffffffu,s,2); s+=__shfl_xor_sync(0xffffffffu,s,1);
    const float inv=rsqrtf(s*(1.0f/D)+eps);
    float yv[8]; for(int i=0;i<8;++i) yv[i]=(xv[j][i]*inv)*wv[i];
    if(R==1||tok0+j<n_tok) st8_h(y+((size_t)(tok0+j)*H+head)*D+c,yv,pol);
  }
}
#define K(name,T,R,ATTR) extern "C" __global__ void ATTR __launch_bounds__(T) name(const float* q,const float* k,const float* wq,const float* wk,float* qo,float* ko,int n,float e){body<T,R>(q,k,wq,wk,qo,ko,n,e);}
#define C2 __cluster_dims__(2,1,1)
K(p256r1,256,1,)
K(c256r1,256,1,C2)
K(c256r2,256,2,C2)
K(p256r2,256,2,)
K(c128r2,128,2,C2)
K(c384r1,384,1,C2)
K(c768r1,768,1,C2)
K(c128r1,128,1,C2)
'''
V=['p256r1','c256r1','c256r2','p256r2','c128r2','c384r1','c768r1']
ks={n:bp.cuda_kernel(SRC,n) for n in V}
print(bp.resources(SRC)[:600] if isinstance(bp.resources(SRC),str) else bp.resources(SRC))
wq=torch.randn(48,128,device='cuda'); wk=torch.randn(48,128,device='cuda')
def cfg(n):
    T=int(n[1:4]); R=int(n[-1]); return T,R
def mk(n,tok):
    T,R=cfg(n); NG=48//(T//16); G=2*NG*((tok+R-1)//R); kk=ks[n]
    return lambda q,k,wq,wk,qo,ko: kk((G,),(T,),q,k,wq,wk,qo,ko,tok,1e-6)
ref=lambda x,w: (x*torch.rsqrt(x.pow(2).mean(-1,keepdim=True)+1e-6)*w.repeat(x.shape[0]//48,1))
for tok in (128,131,256):
    nr=tok*48; q=torch.randn(nr,128,device='cuda'); k=torch.randn_like(q); qo=torch.empty_like(q); ko=torch.empty_like(q)
    for n in V:
        qo.zero_(); ko.zero_(); mk(n,tok)(q,k,wq,wk,qo,ko); torch.cuda.synchronize()
        e=max(float((qo-ref(q,wq)).abs().max()),float((ko-ref(k,wk)).abs().max()))
        if e>1e-4: print('BAD',n,tok,e)
    res={n:[] for n in V}
    for rep in range(10):
        for n in (V if rep%2==0 else V[::-1]):
            res[n].append(bp.harness_time(mk(n,tok),[q,k,wq,wk],[qo,ko],warmup=5,rep=40))
    base=np.median(res['c256r1'])
    print(tok, ' '.join(f"{n}:{np.median(res[n]):.3f}({100*(np.median(res[n])/base-1):+.1f}%)" for n in V))

